234	func TestCLIRemovalsApplyWritesGraphBack(t *testing.T) {
235		graphPath := writeFile(t, "graph.json", `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]},{"name":"C","upstreams":["B"]}]}`)
236		planPath := writeFile(t, "plan.json", `{"changes":[{"name":"D","upstreams":[]},{"name":"B","upstreams":["D"]}],"removals":["A"]}`)
237	
238		stdout, stderr, exit := captureStdout(t, func() int {
239			return run([]string{"apply", graphPath, planPath})
240		})
241		if exit != 0 {
242			t.Fatalf("apply exit = %d, stderr = %s", exit, stderr)
243		}
244		if !strings.Contains(stdout, `"removedDatasets"`) {
245			t.Errorf("apply stdout missing removedDatasets: %s", stdout)
246		}
247		// The graph file must now reflect the final graph: A gone, B depends on D.
