284		var out1, err1, out2, err2 bytes.Buffer
285		cmd1 := exec.Command(snapshotCLIBin, "snapshot", firstGraph, target)
286		cmd1.Stdout, cmd1.Stderr = &out1, &err1
287		cmd2 := exec.Command(snapshotCLIBin, "snapshot", secondGraph, target)
288		cmd2.Stdout, cmd2.Stderr = &out2, &err2
289	
290		if err := cmd1.Start(); err != nil {
291			t.Fatalf("start first snapshot command: %v", err)
292		}
293		if err := cmd2.Start(); err != nil {
294			t.Fatalf("start second snapshot command: %v", err)
295		}
296		waitUntilAllBlocked(t, lockPath, map[int]bool{
297			cmd1.Process.Pid: true,
298			cmd2.Process.Pid: true,
299		})
300	
301		gate.release()
302		waitCommandProcess(t, cmd1)
303		waitCommandProcess(t, cmd2)
304	
305		return procResult{
306				label:       "first",
307				stdout:      out1.String(),
308				stderr:      err1.String(),
309				exitCode:    cmd1.ProcessState.ExitCode(),
310				sourceGraph: firstGraph,
311			}, procResult{
312				label:       "second",
313				stdout:      out2.String(),
314				stderr:      err2.String(),
315				exitCode:    cmd2.ProcessState.ExitCode(),
316				sourceGraph: secondGraph,
317			}
318	}
319	
320	// mustSnapshotFromGraph builds the expected snapshot for a graph JSON string
321	// the same way the command does, so the test can compare content id and the
322	// normalized graph without hardcoding hashes.
323	func mustSnapshotFromGraph(t *testing.T, graphJSON string) *chainledger.SnapshotFile {
324		t.Helper()
325		graph, err := chainledger.UnmarshalGraphFile([]byte(graphJSON))
326		if err != nil {
327			t.Fatalf("invalid reference graph: %v", err)
328		}
329		snap, err := chainledger.BuildSnapshot(graph)
330		if err != nil {
331			t.Fatalf("build reference snapshot: %v", err)
332		}
333		return snap
334	}
335	
336	// rootNames traces dataset in snap and returns the sorted root sources the
337	// stored lineage actually reaches.
338	func rootNames(t *testing.T, snap *chainledger.SnapshotFile, dataset string) []string {
339		t.Helper()
340		report, err := chainledger.TraceSources(snap, dataset)
341		if err != nil {
342			t.Fatalf("trace %q: %v", dataset, err)
343		}
344		roots := make([]string, 0, len(report.Sources))
345		for _, src := range report.Sources {
346			roots = append(roots, src.Root)
347		}
348		return roots
349	}
350	
351	// assertNoLeftoverTempFiles fails if the atomic-write temp pattern left any
352	// half snapshot behind in the target directory.
353	func assertNoLeftoverTempFiles(t *testing.T, dir string) {
354		t.Helper()
355		entries, err := os.ReadDir(dir)
356		if err != nil {
357			t.Fatalf("read target dir: %v", err)
358		}
359		for _, entry := range entries {
360			if strings.HasPrefix(entry.Name(), ".chainledger-") {
361				t.Errorf("rejected/failed save left a temporary file %q", filepath.Join(dir, entry.Name()))
362			}
363		}
364	}
365	
366	// writeRoundInput writes one source graph file and returns its path and exact
367	// bytes, so the test can later prove the source graph was never modified.
368	func writeRoundInput(t *testing.T, dir, name, content string) (path string, raw []byte) {
369		t.Helper()
370		path = filepath.Join(dir, name)
371		raw = []byte(content)
372		if err := os.WriteFile(path, raw, 0o644); err != nil {
373			t.Fatalf("write %s: %v", name, err)
374		}
375		return path, raw
376	}
377	
378	// Two valid but semantically different graphs: the same derived datasets
379	// "report"/"events" reach different root sources.
380	const concurrentGraphRootA = `{"datasets":[` +
381		`{"name":"report","upstreams":["events"]},` +
382		`{"name":"events","upstreams":["chain-A"]},` +
383		`{"name":"chain-A","upstreams":[]}]}`
384	
385	const concurrentGraphRootB = `{"datasets":[` +
386		`{"name":"report","upstreams":["events"]},` +
387		`{"name":"events","upstreams":["chain-B"]},` +
388		`{"name":"chain-B","upstreams":[]}]}`
389	
390	// TestCrossProcessSnapshotDifferentContentExactlyOneWins submits two
391	// independent command processes simultaneously against a not-yet-existing
392	// target, each reading a legal but semantically different graph. Exactly one
393	// must win; which one is not fixed. The test runs both launch orders and
394	// accepts either winner, fully checking outcomes against the winner each time.
395	func TestCrossProcessSnapshotDifferentContentExactlyOneWins(t *testing.T) {
396		wantA := mustSnapshotFromGraph(t, concurrentGraphRootA)
397		wantB := mustSnapshotFromGraph(t, concurrentGraphRootB)
398		if wantA.ContentID == wantB.ContentID {
399			t.Fatal("test setup: the two graphs must have different content identifiers")
400		}
401	
402		const rounds = 8
403		wins := map[string]int{"chain-A": 0, "chain-B": 0}
404		for round := 0; round < rounds; round++ {
405			dir := t.TempDir()
406			graphAPath, graphABytes := writeRoundInput(t, dir, "graph-a.json", concurrentGraphRootA)
407			graphBPath, graphBBytes := writeRoundInput(t, dir, "graph-b.json", concurrentGraphRootB)
408			target := filepath.Join(dir, "snapshot.json")
409			if _, err := os.Stat(target); !os.IsNotExist(err) {
410				t.Fatalf("round %d: target must not exist before the saves", round)
411			}
412	
413			// Alternate launch order; thanks to the gate both are always blocked
414			// together, so the order cannot predetermine the winner.
415			var first, second procResult
416			if round%2 == 0 {
417				first, second = launchConcurrentSnapshotPair(t, target, graphAPath, graphBPath)
418			} else {
419				first, second = launchConcurrentSnapshotPair(t, target, graphBPath, graphAPath)
420			}
421			results := []procResult{first, second}
422	
423			var winner, loser *procResult
424			for i := range results {
425				switch results[i].exitCode {
426				case 0:
427					if winner != nil {
428						t.Fatalf("round %d: both saves succeeded (%s and %s), want exactly one",
429							round, winner.label, results[i].label)
430					}
431					w := results[i]
432					winner = &w
433				default:
434					l := results[i]
435					loser = &l
436				}
437			}
438			if winner == nil {
439				t.Fatalf("round %d: both saves failed, want exactly one winner\nstderr1: %s\nstderr2: %s",
440					round, first.stderr, second.stderr)
441			}
442			if loser == nil {
443				t.Fatalf("round %d: no save was rejected", round)
444			}
445	
446			// Identify the winning graph from the path the winning command read.
447			var winnerRoot string
448			var winnerWant *chainledger.SnapshotFile
449			switch winner.sourceGraph {
450			case graphAPath:
451				winnerRoot, winnerWant = "chain-A", wantA
452			case graphBPath:
453				winnerRoot, winnerWant = "chain-B", wantB
454			default:
455				t.Fatalf("round %d: winner read unknown graph %q", round, winner.sourceGraph)
456			}
457			loserRoot := map[string]string{"chain-A": "chain-B", "chain-B": "chain-A"}[winnerRoot]
458			wins[winnerRoot]++
459	
460			// Winner: exit 0 and stdout contains ONLY the id of what it saved.
461			if winner.stdout != winnerWant.ContentID+"\n" {
462				t.Errorf("round %d: winner stdout = %q, want exactly %q",
463					round, winner.stdout, winnerWant.ContentID)
464			}
465			if winner.stderr != "" {
466				t.Errorf("round %d: winner stderr = %q, want empty", round, winner.stderr)
467			}
468			// Loser: non-zero exit, empty stdout, stderr explains the target
469			// already holds different content and names the target path.
470			if loser.exitCode == 0 {
471				t.Errorf("round %d: rejected save returned exit code 0, want non-zero", round)
472			}
473			if loser.stdout != "" {
474				t.Errorf("round %d: loser stdout = %q, want empty", round, loser.stdout)
475			}
476			if !strings.Contains(loser.stderr, "already holds a different snapshot") {
477				t.Errorf("round %d: loser stderr = %q, want it to explain the target already holds a different snapshot",
478					round, loser.stderr)
479			}
480			if !strings.Contains(loser.stderr, target) {
481				t.Errorf("round %d: loser stderr = %q, want it to name the target path %q",
482					round, loser.stderr, target)
483			}
484	
485			// The target must be one complete, readable snapshot — never a half
486			// file — and the winner's printed id, the file's contentId, and the
487			// stored graph must all describe the SAME graph.
488			finalBytes, err := os.ReadFile(target)
489			if err != nil {
490				t.Fatalf("round %d: target missing/unreadable after both saves: %v", round, err)
491			}
492			finalSnap, err := chainledger.ParseSnapshot(finalBytes)
493			if err != nil {
494				t.Fatalf("round %d: target is not a valid snapshot after the race:\n%s\nerr: %v",
495					round, finalBytes, err)
496			}
497			if finalSnap.ContentID != winnerWant.ContentID {
498				t.Errorf("round %d: target contentId %q != winner %q (loser root %s)",
499					round, finalSnap.ContentID, winnerWant.ContentID, loserRoot)
500			}
501			if !reflect.DeepEqual(finalSnap.Graph, winnerWant.Graph) {
502				t.Errorf("round %d: stored graph does not match the winning graph %q:\ngot:  %+v\nwant: %+v",
503					round, winnerRoot, finalSnap.Graph, winnerWant.Graph)
504			}
505			// The other version's root must not have leaked into the winner.
506			for _, ds := range finalSnap.Graph.Datasets {
507				if ds.Name == loserRoot {
508					t.Errorf("round %d: loser root %q leaked into the winning snapshot", round, loserRoot)
509				}
510			}
511			// Direct upstream chain preserved end to end: the shared derived
512			// dataset traces to the winner's root only.
513			if got := rootNames(t, finalSnap, "report"); !reflect.DeepEqual(got, []string{winnerRoot}) {
514				t.Errorf("round %d: report roots = %v, want [%s]", round, got, winnerRoot)
515			}
516			if got := rootNames(t, finalSnap, "events"); !reflect.DeepEqual(got, []string{winnerRoot}) {
517				t.Errorf("round %d: events roots = %v, want [%s]", round, got, winnerRoot)
518			}
519			// The on-disk bytes are exactly the canonical snapshot of the winner.
520			wantBytes, err := chainledger.MarshalSnapshot(winnerWant)
521			if err != nil {
522				t.Fatalf("marshal expected snapshot: %v", err)
523			}
524			if !bytes.Equal(finalBytes, wantBytes) {
525				t.Errorf("round %d: target bytes are not the canonical winner bytes", round)
526			}
527	
528			// Both source graphs remain byte-for-byte untouched.
529			if got, err := os.ReadFile(graphAPath); err != nil || !bytes.Equal(got, graphABytes) {
530				t.Errorf("round %d: source graph A was modified", round)
531			}
532			if got, err := os.ReadFile(graphBPath); err != nil || !bytes.Equal(got, graphBBytes) {
533				t.Errorf("round %d: source graph B was modified", round)
534			}
535			assertNoLeftoverTempFiles(t, dir)
536		}
537		t.Logf("rounds=%d winner distribution: chain-A=%d chain-B=%d (either winner is correct)",
538			rounds, wins["chain-A"], wins["chain-B"])
539	}
540	
541	// Two byte-different encodings of ONE graph: different record order, upstream
542	// order, a duplicated upstream, and JSON whitespace. Semantically identical,
543	// so they share one content id and one canonical byte form.
544	const equivalentGraphForm1 = `{"datasets":[` +
545		`{"name":"derived","upstreams":["root-b","root-a","root-b"]},` +
546		`{"name":"root-a","upstreams":[]},` +
547		`{"name":"root-b","upstreams":[]}]}`
548	
549	const equivalentGraphForm2 = `{
550	  "datasets": [
551	    { "name": "root-b", "upstreams": [ ] },
552	    { "name": "derived", "upstreams": ["root-a", "root-b"] },
553	    { "name": "root-a", "upstreams": [] }
554	  ]
555	}`
556	
557	// TestCrossProcessSnapshotSemanticallyEqualBothSucceed submits two independent
558	// processes simultaneously with semantically equal inputs (different record
559	// order, upstream order, duplicate upstream, whitespace). Both must succeed and
560	// report the same id, and the created snapshot follows the existing sorting
561	// and de-duplication rules.
562	func TestCrossProcessSnapshotSemanticallyEqualBothSucceed(t *testing.T) {
563		want1 := mustSnapshotFromGraph(t, equivalentGraphForm1)
564		want2 := mustSnapshotFromGraph(t, equivalentGraphForm2)
565		if want1.ContentID != want2.ContentID {
566			t.Fatalf("test setup: equivalent graphs got different ids %q vs %q",
567				want1.ContentID, want2.ContentID)
568		}
569		wantBytes, err := chainledger.MarshalSnapshot(want1)
570		if err != nil {
571			t.Fatalf("marshal canonical snapshot: %v", err)
572		}
573	
574		dir := t.TempDir()
575		graph1Path, _ := writeRoundInput(t, dir, "form1.json", equivalentGraphForm1)
576		graph2Path, graph2Raw := writeRoundInput(t, dir, "form2.json", equivalentGraphForm2)
577		target := filepath.Join(dir, "snapshot.json")
578	
579		first, second := launchConcurrentSnapshotPair(t, target, graph1Path, graph2Path)
580		for _, res := range []procResult{first, second} {
581			if res.exitCode != 0 {
582				t.Errorf("%s save of semantically equal content exited %d: %s",
583					res.label, res.exitCode, res.stderr)
584			}
585			if res.stdout != want1.ContentID+"\n" {
586				t.Errorf("%s stdout = %q, want exactly %q", res.label, res.stdout, want1.ContentID)
587			}
588			if res.stderr != "" {
589				t.Errorf("%s stderr = %q, want empty", res.label, res.stderr)
590			}
591		}
592	
593		finalBytes, err := os.ReadFile(target)
594		if err != nil {
595			t.Fatalf("target unreadable: %v", err)
596		}
597		finalSnap, err := chainledger.ParseSnapshot(finalBytes)
598		if err != nil {
599			t.Fatalf("target is not a valid snapshot: %v\n%s", err, finalBytes)
600		}
601		if finalSnap.ContentID != want1.ContentID {
602			t.Errorf("target contentId %q, want %q", finalSnap.ContentID, want1.ContentID)
603		}
604		if !bytes.Equal(finalBytes, wantBytes) {
605			t.Errorf("created snapshot bytes do not follow canonical sorting/dedup:\ngot:\n%s\nwant:\n%s",
606				finalBytes, wantBytes)
607		}
608		// Explicitly verify ordering and duplicate removal inside the graph.
609		gotNames := make([]string, 0, len(finalSnap.Graph.Datasets))
610		for _, ds := range finalSnap.Graph.Datasets {
611			gotNames = append(gotNames, ds.Name)
612		}
613		if !sort.StringsAreSorted(gotNames) {
614			t.Errorf("datasets not sorted by name: %v", gotNames)
615		}
616		for _, ds := range finalSnap.Graph.Datasets {
617			if !sort.StringsAreSorted(ds.Upstreams) {
618				t.Errorf("upstreams of %q not sorted: %v", ds.Name, ds.Upstreams)
619			}
620			seen := map[string]bool{}
621			for _, u := range ds.Upstreams {
622				if seen[u] {
623					t.Errorf("upstream %q duplicated under %q", u, ds.Name)
624				}
625				seen[u] = true
626			}
627		}
628		if got := rootNames(t, finalSnap, "derived"); !reflect.DeepEqual(got, []string{"root-a", "root-b"}) {
629			t.Errorf("derived roots = %v, want [root-a root-b]", got)
630		}
631		if got, err := os.ReadFile(graph2Path); err != nil || !bytes.Equal(got, graph2Raw) {
632			t.Errorf("source graph form2 was modified")
633		}
634		assertNoLeftoverTempFiles(t, dir)
635	}
636	
637	// saveOnce runs one snapshot command to completion, returning its result.
638	func saveOnce(t *testing.T, graphPath, target string) procResult {
639		t.Helper()
640		var stdout, stderr bytes.Buffer
641		cmd := exec.Command(snapshotCLIBin, "snapshot", graphPath, target)
642		cmd.Stdout, cmd.Stderr = &stdout, &stderr
643		if err := cmd.Run(); err != nil {
644			if cmd.ProcessState == nil {
645				t.Fatalf("seed snapshot failed to run: %v", err)
646			}
647		}
648		return procResult{
649			stdout:   stdout.String(),
650			stderr:   stderr.String(),
651			exitCode: cmd.ProcessState.ExitCode(),
652		}
653	}
654	
655	// TestCrossProcessSnapshotPreexistingSameContentUntouched seeds the target with
656	// a valid snapshot of the same content, then submits two simultaneous saves
657	// (each reading a different equivalent encoding). Both must succeed and the
658	// existing file must remain byte-for-byte and mtime identical — no rewrite.
659	func TestCrossProcessSnapshotPreexistingSameContentUntouched(t *testing.T) {
660		want := mustSnapshotFromGraph(t, equivalentGraphForm1)
661	
662		dir := t.TempDir()
663		graph1Path, _ := writeRoundInput(t, dir, "form1.json", equivalentGraphForm1)
664		graph2Path, graph2Raw := writeRoundInput(t, dir, "form2.json", equivalentGraphForm2)
665		target := filepath.Join(dir, "snapshot.json")
666	
667		seed := saveOnce(t, graph1Path, target)
668		if seed.exitCode != 0 {
669			t.Fatalf("seed snapshot exited %d: %s", seed.exitCode, seed.stderr)
670		}
671		seedBytes, err := os.ReadFile(target)
672		if err != nil {
673			t.Fatalf("read seed snapshot: %v", err)
674		}
675		infoBefore, err := os.Stat(target)
676		if err != nil {
677			t.Fatalf("stat seed snapshot: %v", err)
678		}
679	
680		first, second := launchConcurrentSnapshotPair(t, target, graph1Path, graph2Path)
681		for _, res := range []procResult{first, second} {
682			if res.exitCode != 0 {
683				t.Errorf("%s save over identical content exited %d: %s",
684					res.label, res.exitCode, res.stderr)
685			}
686			if res.stdout != want.ContentID+"\n" {
687				t.Errorf("%s stdout = %q, want exactly %q", res.label, res.stdout, want.ContentID)
688			}
689			if res.stderr != "" {
690				t.Errorf("%s stderr = %q, want empty", res.label, res.stderr)
691			}
692		}
693	
694		gotBytes, err := os.ReadFile(target)
695		if err != nil {
696			t.Fatalf("read target after saves: %v", err)
697		}
698		if !bytes.Equal(gotBytes, seedBytes) {
699			t.Errorf("identical-content concurrent saves rewrote the target:\nbefore: %x\nafter:  %x",
700				seedBytes, gotBytes)
701		}
702		infoAfter, err := os.Stat(target)
703		if err != nil {
704			t.Fatalf("stat target after saves: %v", err)
705		}
706		if !infoAfter.ModTime().Equal(infoBefore.ModTime()) {
707			t.Errorf("identical-content concurrent saves changed mtime: %s -> %s",
708				infoBefore.ModTime(), infoAfter.ModTime())
709		}
710		// The untouched file still reads as the same valid snapshot.
711		if _, err := chainledger.ParseSnapshot(gotBytes); err != nil {
712			t.Errorf("preexisting snapshot unreadable after concurrent saves: %v", err)
713		}
714		if got, err := os.ReadFile(graph2Path); err != nil || !bytes.Equal(got, graph2Raw) {
715			t.Errorf("source graph form2 was modified")
716		}
717		assertNoLeftoverTempFiles(t, dir)
718	}
