1	//go:build linux
2	
3	package main
4	
5	// Regression coverage for the graph-file write-back contract of a lineage
6	// batch adjustment.
7	//
8	// A valid, accepted plan does not by itself mean the adjustment is committed:
9	// apply must still save the final graph back to the graph file. The product
10	// promises that a failure at the SAVE stage — after the graph and plan were
11	// read and the adjustment fully validated —
12	//
13	//   - returns a non-zero process exit code,
14	//   - reports the graph file and the save failure on stderr,
15	//   - prints no success report on stdout,
16	//   - leaves the original graph file byte-for-byte intact (its JSON
17	//     whitespace, field order, and unknown fields the reader ignores),
18	//   - leaves the plan file intact,
19	//
20	// because the save goes through a temp file plus an atomic rename. The
21	// matching control proves a successful save really commits: the graph file
22	// re-reads to the same relations the preview showed, and the apply report is
23	// byte-identical to the preview report for the same inputs. That keeps "the
24	// plan is valid" and "the adjustment was saved" as two distinguishable,
25	// observable outcomes.
26	//
27	// Both save faults are provoked deterministically offline:
28	//
29	//   - temp-file creation denied: the graph's directory is chmod 0500, so the
30	//     files remain readable (validation still passes) but creating the temp
31	//     file fails with EACCES;
32	//   - final rename denied: the command runs in a private user+mount namespace
33	//     with the graph file bind-mounted onto itself, so the temp file is fully
34	//     written and only the rename-over-original fails with EBUSY (see
35	//     save_fault_helper_linux_test.go).
36	//
37	// No chain network, external service, real disk fault, or product seam is
38	// used; command arguments, the report structure, and the lineage rules are
39	// unchanged.
40	
41	import (
42		"bytes"
43		"encoding/json"
44		"os"
45		"os/exec"
46		"path/filepath"
47		"reflect"
48		"strings"
49		"testing"
50	
51		"github.com/asdhoaiqqq/chainledger-governance/chainledger"
52	)
53	
54	// The adjustment used throughout this regression. The original graph has two
55	// roots, A and D: B depends directly on A and C depends directly on B. The
56	// plan replaces all of B's direct upstreams with D; everything else is kept.
57	//
58	// The graph bytes deliberately carry details a successful save would rewrite
59	// or drop: non-canonical whitespace/indentation, an "upstreams" field written
60	// before "name" in B's record, an unknown top-level field with a nested
61	// object, and an unknown field inside B's record (both ignored by the reader).
62	// A failed save must preserve all of these byte-for-byte.
63	const saveFaultGraphJSON = `{
64	  "_provenance": {"exportedBy": "nightly-job", "retentionDays": 30},
65	  "datasets": [
66	    {"name": "A", "upstreams": []},
67	    {"upstreams": ["A"], "name": "B", "_qualityNote": "stable since v3"},
68	    {"name": "C", "upstreams": ["B"]},
69	    {"name": "D", "upstreams": []}
70	  ]
71	}`
72	
73	const saveFaultPlanJSON = `{"changes":[{"name":"B","upstreams":["D"]}]}`
74	
75	// saveFaultInputs writes a fresh graph and plan file in a new temp directory
76	// and returns the directory and both paths.
77	func saveFaultInputs(t *testing.T) (dir, graphPath, planPath string) {
78		t.Helper()
79		dir = t.TempDir()
80		graphPath, _ = writeRoundInput(t, dir, "graph.json", saveFaultGraphJSON)
81		planPath, _ = writeRoundInput(t, dir, "plan.json", saveFaultPlanJSON)
82		return dir, graphPath, planPath
83	}
84	
85	// runBuiltCommand runs the freshly built command binary with argv and returns
86	// its stdout, stderr, and real process exit code.
87	func runBuiltCommand(t *testing.T, argv ...string) (stdout, stderr string, exitCode int) {
88		t.Helper()
89		cmd := exec.Command(snapshotCLIBin, argv...)
90		var outBuf, errBuf bytes.Buffer
91		cmd.Stdout, cmd.Stderr = &outBuf, &errBuf
92		if err := cmd.Run(); err != nil {
93			if cmd.ProcessState == nil {
94				t.Fatalf("command %v failed to run: %v", argv, err)
95			}
96		}
97		return outBuf.String(), errBuf.String(), cmd.ProcessState.ExitCode()
98	}
99	
100	// rerootGoldenReport computes, purely in memory, the report preview/apply must
101	// produce for saveFaultGraphJSON + saveFaultPlanJSON. Building it through the
102	// library instead of hardcoding JSON also proves the inputs really parse and
103	// validate.
104	func rerootGoldenReport(t *testing.T) *chainledger.BatchReport {
105		t.Helper()
106		graph, err := chainledger.UnmarshalGraphFile([]byte(saveFaultGraphJSON))
107		if err != nil {
108			t.Fatalf("test graph must be valid: %v", err)
109		}
110		plan, err := chainledger.UnmarshalPlan([]byte(saveFaultPlanJSON))
111		if err != nil {
112			t.Fatalf("test plan must be valid: %v", err)
113		}
114		report, err := chainledger.PreviewBatch(graph, plan)
115		if err != nil {
116			t.Fatalf("preview of the test adjustment must succeed: %v", err)
117		}
118		return report
119	}
120	
121	// assertRerootReportShape pins down, in human terms, what the one adjustment
122	// does: B is the only directly changed dataset, C its affected downstream,
123	// the only relation changes are A->B removed and D->B added, no dataset is
124	// added or removed, and the final graph has B depending on D while C still
125	// depends on B.
126	func assertRerootReportShape(t *testing.T, report *chainledger.BatchReport) {
127		t.Helper()
128		if got := report.NewDatasets; !reflect.DeepEqual(got, []string{}) {
129			t.Errorf("newDatasets = %v, want []", got)
130		}
131		if got := report.ChangedDatasets; !reflect.DeepEqual(got, []string{"B"}) {
132			t.Errorf("changedDatasets = %v, want [B]", got)
133		}
134		if got := report.RemovedDatasets; !reflect.DeepEqual(got, []string{}) {
135			t.Errorf("removedDatasets = %v, want []", got)
136		}
137		wantAdded := []chainledger.Relation{{Upstream: "D", Downstream: "B"}}
138		if got := report.AddedRelations; !reflect.DeepEqual(got, wantAdded) {
139			t.Errorf("addedRelations = %v, want %v", got, wantAdded)
140		}
141		wantRemoved := []chainledger.Relation{{Upstream: "A", Downstream: "B"}}
142		if got := report.RemovedRelations; !reflect.DeepEqual(got, wantRemoved) {
143			t.Errorf("removedRelations = %v, want %v", got, wantRemoved)
144		}
145		if got := report.AffectedDownstreams; !reflect.DeepEqual(got, []string{"C"}) {
146			t.Errorf("affectedDownstreams = %v, want [C]", got)
147		}
148		wantParents := map[string][]string{
149			"A": {},
150			"B": {"D"},
151			"C": {"B"},
152			"D": {},
153		}
154		gotParents := make(map[string][]string, len(report.FinalGraph.Datasets))
155		for _, ds := range report.FinalGraph.Datasets {
156			gotParents[ds.Name] = ds.Upstreams
157		}
158		if !reflect.DeepEqual(gotParents, wantParents) {
159			t.Errorf("final graph relations = %v, want %v", gotParents, wantParents)
160		}
161	}
162	
163	// decodeBatchReport parses one printed report.
164	func decodeBatchReport(t *testing.T, raw string) chainledger.BatchReport {
165		t.Helper()
166		var report chainledger.BatchReport
167		if err := json.Unmarshal([]byte(raw), &report); err != nil {
168			t.Fatalf("stdout is not a valid batch report:\n%s\nerr: %v", raw, err)
169		}
170		return report
171	}
172	
173	// assertInputsPreserved fails unless both files still hold their exact
174	// original bytes, and no atomic-write temp file was left behind.
175	func assertInputsPreserved(t *testing.T, dir, graphPath, planPath string) {
176		t.Helper()
177		if got, err := os.ReadFile(graphPath); err != nil || !bytes.Equal(got, []byte(saveFaultGraphJSON)) {
178			t.Errorf("graph file not preserved byte-for-byte:\n got %q\nwant %q (err=%v)", got, saveFaultGraphJSON, err)
179		}
180		if got, err := os.ReadFile(planPath); err != nil || !bytes.Equal(got, []byte(saveFaultPlanJSON)) {
181			t.Errorf("plan file changed after apply:\n got %q\nwant %q (err=%v)", got, saveFaultPlanJSON, err)
182		}
183		assertNoLeftoverTempFiles(t, dir)
184	}
185	
186	// TestCLIBatchRerootPreviewReport pins the adjustment itself: preview of the
187	// same inputs succeeds with B rerooted onto D, C still on B, only B directly
188	// changed, C the sole affected downstream, and just the A->B / D->B relation
189	// changes. Preview must never alter either input file.
190	func TestCLIBatchRerootPreviewReport(t *testing.T) {
191		golden := rerootGoldenReport(t)
192		assertRerootReportShape(t, golden)
193	
194		_, graphPath, planPath := saveFaultInputs(t)
195		dir := filepath.Dir(graphPath)
196		stdout, stderr, exitCode := runBuiltCommand(t, "preview", graphPath, planPath)
197		if exitCode != 0 {
198			t.Fatalf("preview exit = %d, stderr = %s", exitCode, stderr)
199		}
200		printed := decodeBatchReport(t, stdout)
201		if !reflect.DeepEqual(&printed, golden) {
202			t.Errorf("printed preview report does not match the computed report:\n got %+v\nwant %+v", printed, golden)
203		}
204		// Preview is strictly read-only: both files keep their exact bytes.
205		assertInputsPreserved(t, dir, graphPath, planPath)
206	}
207	
208	// TestCLIBatchApplyTempFileCreationFailure covers the first save fault: the
209	// graph and plan are readable and the batch validates (preview on the same
210	// files succeeds first), but the graph's directory refuses to create the temp
211	// file. Apply must fail cleanly and preserve the original graph bytes.
212	func TestCLIBatchApplyTempFileCreationFailure(t *testing.T) {
213		dir, graphPath, planPath := saveFaultInputs(t)
214	
215		// Establish the precondition: files readable and the adjustment valid.
216		if _, stderr, code := runBuiltCommand(t, "preview", graphPath, planPath); code != 0 {
217			t.Fatalf("preview must succeed before the save fault is injected: %s", stderr)
218		}
219	
220		// Drop write permission on the directory only: files stay readable (the
221		// command still validates the batch), but CreateTemp in this directory is
222		// refused with EACCES. Restore it afterwards so temp-dir cleanup works.
223		if err := os.Chmod(dir, 0o500); err != nil {
224			t.Fatalf("chmod graph directory: %v", err)
225		}
226		t.Cleanup(func() { _ = os.Chmod(dir, 0o700) })
227	
228		stdout, stderr, exitCode := runBuiltCommand(t, "apply", graphPath, planPath)
229		if exitCode == 0 {
230			t.Fatalf("apply exit = 0, want non-zero when the temp file cannot be created")
231		}
232		if stdout != "" {
233			t.Errorf("stdout = %q, want no success report on save failure", stdout)
234		}
235		if !strings.Contains(stderr, graphPath) {
236			t.Errorf("stderr = %q, want it to name the graph file %q", stderr, graphPath)
237		}
238		if !strings.Contains(stderr, "cannot write graph file") {
239			t.Errorf("stderr = %q, want it to report the graph-file save failure", stderr)
240		}
241		if !strings.Contains(stderr, "permission denied") {
242			t.Errorf("stderr = %q, want the save-failure reason (permission denied)", stderr)
243		}
244	
245		_ = os.Chmod(dir, 0o700)
246		assertInputsPreserved(t, dir, graphPath, planPath)
247	}
248	
249	// TestCLIBatchApplyRenameFailure covers the second save fault: inside a
250	// private user+mount namespace the graph file is bind-mounted onto itself, so
251	// the temp file is created and fully written but the final rename over the
252	// original fails with EBUSY. Apply must fail cleanly and preserve the
253	// original graph bytes.
254	func TestCLIBatchApplyRenameFailure(t *testing.T) {
255		dir, graphPath, planPath := saveFaultInputs(t)
256	
257		// Establish the precondition on the host: files readable, batch valid.
258		if _, stderr, code := runBuiltCommand(t, "preview", graphPath, planPath); code != 0 {
259			t.Fatalf("preview must succeed before the save fault is injected: %s", stderr)
260		}
261	
262		stdout, stderr, exitCode, startErr := runInMountNamespace(
263			t, snapshotCLIBin, []string{"apply", graphPath, planPath}, graphPath)
264		if startErr != nil {
265			t.Skipf("unprivileged user+mount namespaces unavailable in this environment: %v", startErr)
266		}
267		// Helper setup failures (cannot privatize mounts / cannot bind-mount) are
268		// environment limits, not product behavior; skip rather than fail.
269		switch exitCode {
270		case 10, 11:
271			t.Skipf("mount-namespace fault setup unavailable (helper exit %d): %s", exitCode, stderr)
272		case 12:
273			t.Fatalf("fault helper could not exec the command: %s", stderr)
274		}
275		if exitCode == 0 {
276			t.Fatalf("apply exit = 0, want non-zero when the rename cannot replace the graph file")
277		}
278		if stdout != "" {
279			t.Errorf("stdout = %q, want no success report on save failure", stdout)
280		}
281		if !strings.Contains(stderr, graphPath) {
282			t.Errorf("stderr = %q, want it to name the graph file %q", stderr, graphPath)
283		}
284		if !strings.Contains(stderr, "cannot write graph file") {
285			t.Errorf("stderr = %q, want it to report the graph-file save failure", stderr)
286		}
287		if !strings.Contains(stderr, "device or resource busy") {
288			t.Errorf("stderr = %q, want the save-failure reason (device or resource busy)", stderr)
289		}
290	
291		assertInputsPreserved(t, dir, graphPath, planPath)
292	}
293	
294	// TestCLIBatchApplySuccessMatchesPreview is the control the two failures are
295	// judged against: with the save healthy, apply commits. Re-reading the graph
296	// file yields exactly the relations the preview's final graph showed, and the
297	// apply report is byte-identical to the preview report for the same original
298	// graph and plan.
